/**
 * The platform abstraction: the only part a native host implements. Every method blocks
 * its thread until done. `http`, `tool` and `attest` are called on a worker thread; they
 * should honour cancellation (and `http`/`attest` their `timeout_ms`) to free it, but the
 * Runtime does not depend on it: past the deadline the effect has its result and anything
 * late is dropped. `tool` has no deadline of its own: the Runtime is its only clock.
 */
public protocol HostPal: AnyObject, Sendable {
    
    /**
     * Send the request; call `sink.head` once, then `sink.chunk` per piece of body; return
     * when the body ends. Stop when `chunk` returns false or `cancel` fires.
     */
    func http(request: PalHttpRequest, sink: HttpSink, cancel: CancelToken) throws 
    
    func read(key: String) throws  -> String?
    
    /**
     * Replaces the whole value atomically.
     */
    func write(key: String, value: String) throws 
    
    func readSecret(key: String) throws  -> String?
    
    func writeSecret(key: String, value: String) throws 
    
    /**
     * Deletes `key` for real (R8): an absent key is Ok, and never a `null` written over it.
     */
    func remove(key: String) throws 
    
    /**
     * Deletes the secret `key` from where `write_secret` keeps it (the Keychain item itself).
     */
    func removeSecret(key: String) throws 
    
    /**
     * Exclusive ownership of the store (`store_busy` when taken).
     */
    func lock(key: String) throws 
    
    func unlock(key: String) 
    
    /**
     * Identifies the store: two Runtimes on one store in a process are refused.
     */
    func storeIdentity()  -> String
    
    /**
     * `{tool, command?, key, args, context}` → the tool's JSON result. The Runtime times the
     * call: at the command's deadline, or on a cancel, it fires `cancel`, and the host returns
     * promptly whether or not its handler stops (the result is discarded). The host never times
     * a tool itself. No handler for the tool: fail with `tool_not_dispatched` (nothing ran).
     * Its images ride beside the value (H3).
     */
    func tool(invocation: String, cancel: CancelToken) throws  -> ToolOutput
    
    /**
     * `{clientData, clientDataHash, platform}` → `{platform, token, keyId?}`.
     */
    func attest(request: String, timeoutMs: UInt64) throws  -> String
    
    func nowMs()  -> Double
    
    func utcOffsetMinutes(atMs: Double)  -> Int64
    
    func random()  -> String
    
    /**
     * Arm the single upkeep timer: call `tick` at `at_ms` (None: disarm).
     */
    func wake(atMs: Double?) 
    
    /**
     * The agent's whole pending schedule set changed, or the store opened (JSON
     * `[{id, at}]`, `at` ISO UTC). Arm a timer or OS task that calls `deliver_due`, or just
     * return: the notes still come at the next `deliver_due`. An error never fails the turn.
     */
    func schedule(entries: String) throws 
    
    /**
     * The turn archive's line storage (F20.6), the host's `ArchiveRuntimeStorage`: entries
     * `archive<NNNN>` beside the store. A host whose storage keeps no archive fails each call
     * with `archive_unavailable`; the Runtime then keeps no archive and nothing else changes.
     * Appends one line, writing a newline first when the entry does not end with one; durable
     * when it returns.
     */
    func archiveAppendLine(entry: String, line: String) throws 
    
    /**
     * The entry's complete lines in order (a torn last line is not one); empty when absent.
     */
    func archiveReadLines(entry: String) throws  -> [String]
    
    /**
     * Replaces the entry's lines atomically (all old or all new after a crash); empty deletes.
     */
    func archiveReplaceLines(entry: String, lines: [String]) throws 
    
    /**
     * Deletes the entry for real. Absent is not an error.
     */
    func archiveRemove(entry: String) throws 
    
    /**
     * The entries whose names start with `prefix`, with their sizes in bytes.
     */
    func archiveEntries(prefix: String) throws  -> [ArchiveEntry]
    
    /**
     * What the host's storage can keep beside its snapshot (S1, rev 4 §17.13): where the
     * message log goes. `Lines`: the five line calls above, in entries `log<NNNNNN>`, apart from
     * the archive's. `Keyed`: entries `<key>.log<NNNNNN>` through `read` and `write`.
     * `Snapshot`: nothing beside the snapshot; the log is inside it.
     */
    func storageCapability()  -> StorageCapability
    
}
