// Put the implementation in a struct so we don't pollute the top-level namespace
fileprivate struct UniffiCallbackInterfaceHostPalFactory {

    // Create the VTable using a series of closures.
    // Swift automatically converts these into C callback functions.
    //
    // Store the vtable directly.
    static let vtable: UniffiVTableCallbackInterfaceHostPalFactory = UniffiVTableCallbackInterfaceHostPalFactory(
        uniffiFree: { (uniffiHandle: UInt64) -> () in
            do {
                try FfiConverterTypeHostPalFactory.handleMap.remove(handle: uniffiHandle)
            } catch {
                print("Uniffi callback interface HostPalFactory: handle missing in uniffiFree")
            }
        },
        uniffiClone: { (uniffiHandle: UInt64) -> UInt64 in
            do {
                return try FfiConverterTypeHostPalFactory.handleMap.clone(handle: uniffiHandle)
            } catch {
                fatalError("Uniffi callback interface HostPalFactory: handle missing in uniffiClone")
            }
        },
        pal: { (
            uniffiHandle: UInt64,
            agent: RustBuffer,
            uniffiOutReturn: UnsafeMutablePointer<UInt64>,
            uniffiCallStatus: UnsafeMutablePointer<RustCallStatus>
        ) in
            let makeCall = {
                () throws -> HostPal in
                guard let uniffiObj = try? FfiConverterTypeHostPalFactory.handleMap.get(handle: uniffiHandle) else {
                    throw UniffiInternalError.unexpectedStaleHandle
                }
                return uniffiObj.pal(
                     agent: try FfiConverterString.lift(agent)
                )
            }

            
            let writeReturn = { uniffiOutReturn.pointee = FfiConverterTypeHostPal_lower($0) }
            uniffiTraitInterfaceCall(
                callStatus: uniffiCallStatus,
                makeCall: makeCall,
                writeReturn: writeReturn
            )
        }
    )

    // Rust stores this pointer for future callback invocations, so it must live
    // for the process lifetime (not just for the init function call).
    //
    // `nonisolated(unsafe)` is needed under Swift 6 strict concurrency.
    // This is safe because the pointee is initialized once during static init
    // and never mutated by either side of the FFI.  Its fields are C function pointers.
    nonisolated(unsafe) static let vtablePtr: UnsafePointer<UniffiVTableCallbackInterfaceHostPalFactory> = {
        let ptr = UnsafeMutablePointer<UniffiVTableCallbackInterfaceHostPalFactory>.allocate(capacity: 1)
        ptr.initialize(to: vtable)
        return UnsafePointer(ptr)
    }()
}

